/**
 * Stand-in for src/bindings.ts in the unit tests of a checkout without it (the file is generated by the Rust build
 * and git-ignored). vitest.config.ts points `../bindings` imports here only when the generated file is missing. No
 * test reaches the backend: every command and event rejects / does nothing; tests that need a command mock it with
 * vi.mock.
 */
const reject = (name: string) => () => Promise.reject(new Error(`bindings stub: ${name} is not available in unit tests`));

export const commands: Record<string, (...args: unknown[]) => Promise<never>> = new Proxy(
  {},
  { get: (_target, name) => reject(String(name)) },
);

export const events: Record<string, { listen: () => Promise<() => void>; emit: () => Promise<void> }> = new Proxy(
  {},
  { get: () => ({ listen: () => Promise.resolve(() => {}), emit: () => Promise.resolve() }) },
);
